const row = $input.first().json || {};
if (!row.message_id) return [{ json: { skip: true, reason: 'no_queued_message' } }];
if (String(row.message_status || '').toLowerCase() === 'delivered') return [{ json: { skip: true, reason: 'already_delivered', message_id: row.message_id } }];
const provider = String(row.eff_provider || row.provider || 'thikaa').toLowerCase();
const channelType = String(row.type || 'whatsapp').toLowerCase();
const isDirectTelegram = channelType === 'telegram' && provider !== 'meta' && provider !== 'superchat';
const recipient = String(row.recipient || '').trim();
if (!recipient && !isDirectTelegram) return [{ json: { skip: true, reason: 'no_recipient', message_id: row.message_id } }];
const content = String(row.content || '').slice(0, 4000);
const cfg = row.channel_config && typeof row.channel_config === 'object' ? row.channel_config : {};
const superchatApiKey = String(cfg.superchat_api_key || '').trim();
const superchatChannelId = String(cfg.superchat_channel_id || '').trim();
let sendUrl = '', authHeader = '', body = {};
if (isDirectTelegram) {
  const telegramChatId = String(row.channel_conversation_id || '').trim();
  if (!telegramChatId) return [{ json: { skip: true, reason: 'missing_telegram_chat_id', message_id: row.message_id, provider: 'telegram_direct', channelType } }];
  return [{ json: {
    sendUrl: '',
    authHeader: '',
    body: { chat_id: telegramChatId, text: content },
    message_id: row.message_id,
    provider: 'telegram_direct',
    channelType,
    telegram_chat_id: telegramChatId,
    content,
    skip: false,
  } }];
} else if (provider === 'thikaa') {
  const codeMap = { whatsapp: 'wd', messenger: 'fb', instagram: 'ig', telegram: 'tg' };
  body = { channel: codeMap[channelType] || 'wd', to: recipient, message: content };
  sendUrl = 'https://thikaa.com/' + (row.tenant_identifier || '') + '/api/messaging/?action=send';
  authHeader = 'Bearer ' + (row.api_token || '');
} else if (provider === 'meta' && channelType === 'whatsapp') {
  body = { channel: 'whatsapp', source: String(row.gupshup_source || ''), destination: recipient, messageType: { type: 'text', text: content } };
  sendUrl = 'https://api.gupshup.io/wa/api/v1/msg';
  authHeader = 'Bearer ' + (row.api_token || '');
} else if (provider === 'meta' && (channelType === 'instagram' || channelType === 'messenger')) {
  const pid = cfg.meta_phone_number_id || cfg.phone_number_id || '';
  body = { messaging_product: channelType === 'instagram' ? 'instagram' : 'RESPONSE', to: recipient, text: { body: content } };
  sendUrl = channelType === 'instagram' ? 'https://graph.facebook.com/v21.0/me/messages' : 'https://graph.facebook.com/v21.0/' + pid + '/messages';
  authHeader = 'Bearer ' + (row.api_token || '');
} else if (provider === 'superchat' && superchatApiKey && superchatChannelId) {
  return [{ json: { skip: false, needs_superchat_contact: true, message_id: row.message_id, content, recipient, superchat_api_key: superchatApiKey, superchat_channel_id: superchatChannelId, provider, channelType } }];
} else {
  return [{ json: { skip: true, reason: 'unsupported_provider_or_missing_channel_config', provider, channelType, message_id: row.message_id } }];
}
return [{ json: { sendUrl, authHeader, body, message_id: row.message_id, provider, channelType, content, skip: false } }];

const base = $('Build Provider Request').first().json || {};
const results = Array.isArray($json.results) ? $json.results : [];
const target = String(base.recipient || '').trim();
let contactId = null;
for (const contact of results) {
  for (const handle of (Array.isArray(contact?.handles) ? contact.handles : [])) {
    if (String(handle?.value || '').trim() === target) { contactId = contact.id || null; break; }
  }
  if (contactId) break;
}
if (!contactId) return [{ json: { ...base, skip: true, reason: 'no_matching_superchat_contact', message_id: base.message_id } }];
const sendUrl = 'https://api.superchat.com/v1.0/messages';
if (!/^https:\/\/api\.superchat\.com\//i.test(sendUrl)) {
  return [{ json: { ...base, skip: true, reason: 'provider_host_not_allowlisted', message_id: base.message_id } }];
}
return [{ json: { ...base, skip: false, sendUrl, apiKeyHeader: base.superchat_api_key, body: { to: [{ identifier: contactId }], from: { channel_id: base.superchat_channel_id }, content: { type: 'text', body: base.content } }, message_id: base.message_id } }];

const rawInput = $json || {};
const req = $('Build Provider Request').first().json || {};
const provider = String(req.provider || '').toLowerCase();
const channelType = String(req.channelType || '').toLowerCase();
const decodeJsonText = (value) => {
  if (typeof value !== 'string') return value;
  const text = value.trim();
  if (!text) return text;
  try { return JSON.parse(text); } catch (e) { return text; }
};
const decoded = decodeJsonText(rawInput);
const response = decoded && typeof decoded === 'object' && decoded.body !== undefined
  ? decodeJsonText(decoded.body)
  : decoded;
let accepted = false;
let evidence = 'http_2xx_only';
if (provider === 'telegram_direct' && channelType === 'telegram') {
  const telegramMessageId = Number(response?.result?.message_id ?? response?.message_id ?? 0);
  accepted = response?.ok === true || telegramMessageId > 0;
  evidence = accepted ? 'telegram_api_ok_message_id' : 'telegram_acceptance_unverified';
} else if (provider === 'meta' && channelType === 'whatsapp') {
  accepted = response && response.status === 'submitted' && typeof response.messageId === 'string' && response.messageId.trim().length > 0;
  evidence = accepted ? 'gupshup_submitted_messageId' : 'gupshup_acceptance_unverified';
} else if (provider === 'thikaa' || provider === 'superchat' || provider === 'meta') {
  accepted = true;
}
if (!accepted) throw new Error('provider_acceptance_not_verified');
return { json: { ...(decoded && typeof decoded === 'object' ? decoded : {}), provider_acceptance_verified: true, provider_acceptance_evidence: evidence, message_id: req.message_id } };

